await page.evaluate(async () => {
  try {
    const r = await fetch('/robots.txt');
    const robotsPresent = r.ok;
    const txt = robotsPresent ? await r.text() : '';
    const sitemaps = [...new Set(txt.split(/\n/).filter(l => /^\s*Sitemap:/i.test(l)).map(l => l.replace(/^\s*Sitemap:\s*/i, '').trim()))].sort();
    const sr = await fetch('/sitemap.xml');
    let sitemapUrlCount = 0, allSameHost = true;
    if (sr.ok) {
      const xml = await sr.text();
      const doc = new DOMParser().parseFromString(xml, 'application/xml');
      const locs = [...doc.getElementsByTagName('loc')].map(e => e.textContent.trim());
      sitemapUrlCount = locs.length;
      const host = location.hostname;
      allSameHost = locs.every(u => { try { return new URL(u).hostname === host; } catch { return false; } });
    }
    window.__bench_finding = { robotsPresent, robotsSitemaps: sitemaps, sitemapUrlCount, allSameHost };
  } catch (e) {
    window.__bench_finding = { error: String(e) };
  }
  return JSON.stringify(window.__bench_finding);
})

